import { techStack } from "../data/portfolio";
import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

const categoryColors = {
  Backend:  "text-blue-400",
  Frontend: "text-purple-400",
  Mobile:   "text-emerald-400",
  Tools:    "text-amber-400",
};

export default function Stack() {
  const ref = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <section id="stack" className={`py-28 border-t transition-colors duration-300
      ${isDark ? "bg-ink-900 border-wire" : "bg-paper-100 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Tech Stack</p>
          <h2 className="section-title text-3xl sm:text-4xl lg:text-5xl">
            Tools & technologies<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>I work with.</span>
          </h2>
        </div>

        <div ref={ref} className={`fade-up grid sm:grid-cols-2 lg:grid-cols-4 gap-px ${isDark ? "bg-wire" : "bg-wire-light"}`}>
          {Object.entries(techStack).map(([category, items]) => (
            <div key={category} className={`p-8 transition-colors duration-300 ${isDark ? "bg-ink-900" : "bg-paper-100"}`}>
              <div className="mb-6">
                <p className={`font-mono text-xs tracking-[0.2em] uppercase mb-1 ${categoryColors[category]}`}>
                  {category}
                </p>
                <div className={`h-px w-8 ${isDark ? "bg-wire" : "bg-wire-light"}`} />
              </div>
              <ul className="space-y-3">
                {items.map((item) => (
                  <li key={item} className={`flex items-center gap-3 text-sm font-body
                    ${isDark ? "text-stone-300" : "text-gray-700"}`}>
                    <span className={`w-1 h-1 rounded-full flex-shrink-0 ${isDark ? "bg-ink-500" : "bg-gray-300"}`} />
                    {item}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <p className={`mt-10 font-mono text-xs text-right tracking-wider ${isDark ? "text-stone-600" : "text-gray-400"}`}>
          continuously expanding — currently exploring React and Tailwind CSS
        </p>
      </div>
    </section>
  );
}
